-- Catalogo curado a partir de hasaneyldrm/exercises-dataset (datos MIT).
-- Seleccion manual de 198 ejercicios de gimnasio comunes, con el nombre
-- traducido al espanol y el original conservado en name_en para poder buscarlos
-- con cualquiera de los dos.

-- El unico ejercicio que habia era de prueba y ya no lo referencia nadie: la
-- reestructuracion a rutinas y dias borro las tablas que lo usaban.
delete from public.exercises;


create unique index if not exists exercises_slug_key on public.exercises (slug);
alter table public.exercises alter column slug set not null;
